def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_def = sum(1 for a in opp if a == 'D')
    me_def = sum(1 for a in me if a == 'D')
    last_me, last_opp = history[-1]

    # Early opening: cooperate for first 3 rounds, then probe only if opponent has been perfectly cooperative.
    if n < 3:
        return 'C'
    if n == 3:
        if opp_def == 0:
            return 'D'
        return 'C'
    if n == 4:
        if opp_def == 4:
            return 'C'

    # Constant defection.
    if n >= 5 and opp_def == n:
        return 'D'

    # Detect periodic_D pattern (defects on first two positions of each 5-round cycle).
    if n >= 10:
        match1 = 0
        match2 = 0
        for i in range(n - 10, n):
            if opp[i] == ('D' if (i % 5) in (0, 1) else 'C'):
                match1 += 1
            if opp[i] == ('D' if (i % 5) in (1, 2) else 'C'):
                match2 += 1
        if match1 >= 9 or match2 >= 9:
            return 'D'

    # Heavy defector.
    if n >= 10 and opp_def >= n * 0.8:
        return 'D'
    if n >= 20 and opp_def * 3 > n * 2:
        return 'D'

    # If opponent defected last round.
    if last_opp == 'D':
        if opp_def <= n // 3:
            return 'C'
        return 'D'

    # If we defected last round, cooperate to restore.
    if last_me == 'D':
        return 'C'

    # If opponent has a high overall defect rate, defect even if last was C.
    if n >= 10 and opp_def * 2 > n:
        return 'D'

    # Scheduled occasional defection to prevent exploitation.
    if n >= 5 and n % 6 == 0:
        return 'D'

    return 'C'
